/*
 * SYNTHETIC DEMONSTRATION DATA
 * Every value in this file is generated by a seeded pseudo-random function.
 * It does not contain, and is not derived from, any real patient or hospital data.
 */
(function () {
  "use strict";

  function mulberry32(seed) {
    return function () {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  var rand = mulberry32(20261016);
  function noise(spread) { return (rand() * 2 - 1) * spread; }
  function clamp(v, min, max) { return Math.min(max, Math.max(min, v)); }

  var DEPARTMENTS = [
    { id: "emergency", name: "Emergency", beds: 40, admissions: 620, occupancy: 82, los: 0.8, ratio: 4, readmit: 13.5, falls: 2.4, hapi: 0.4, clabsi: 0.2, medErr: 2.6, mortality: 0.9 },
    { id: "icu", name: "Intensive Care", beds: 24, admissions: 95, occupancy: 88, los: 5.6, ratio: 2, readmit: 9.8, falls: 1.6, hapi: 2.6, clabsi: 1.4, medErr: 3.1, mortality: 7.5 },
    { id: "medsurg", name: "Medical-Surgical", beds: 80, admissions: 410, occupancy: 86, los: 4.8, ratio: 5, readmit: 14.2, falls: 3.8, hapi: 1.5, clabsi: 0.7, medErr: 2.3, mortality: 1.6 },
    { id: "cardiology", name: "Cardiology", beds: 36, admissions: 175, occupancy: 81, los: 4.2, ratio: 4, readmit: 15.6, falls: 2.9, hapi: 1.1, clabsi: 0.6, medErr: 2.0, mortality: 2.1 },
    { id: "pediatrics", name: "Pediatrics", beds: 30, admissions: 160, occupancy: 69, los: 3.1, ratio: 4, readmit: 7.2, falls: 1.1, hapi: 0.5, clabsi: 0.4, medErr: 1.7, mortality: 0.2 },
    { id: "maternity", name: "Maternity", beds: 28, admissions: 205, occupancy: 74, los: 2.4, ratio: 4, readmit: 4.8, falls: 0.7, hapi: 0.2, clabsi: 0.1, medErr: 1.3, mortality: 0.1 }
  ];

  var MONTH_NAMES = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  var TOTAL_MONTHS = 24;
  var END_YEAR = 2026;
  var END_MONTH = 9; // October (0-indexed)
  var QI_START_INDEX = 15; // falls & hand hygiene improvement bundle begins

  var months = [];
  for (var i = TOTAL_MONTHS - 1; i >= 0; i--) {
    var d = new Date(END_YEAR, END_MONTH - i, 1);
    months.push({
      key: d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0"),
      label: MONTH_NAMES[d.getMonth()] + " " + String(d.getFullYear()).slice(2),
      month: d.getMonth()
    });
  }

  function seasonality(monthIndex) {
    return 1 + 0.09 * Math.cos(((monthIndex - 0.5) / 12) * Math.PI * 2);
  }

  var records = {};
  DEPARTMENTS.forEach(function (dept) {
    records[dept.id] = months.map(function (m, idx) {
      var season = seasonality(m.month);
      var progress = idx / (TOTAL_MONTHS - 1);
      var qiEffect = idx >= QI_START_INDEX ? (idx - QI_START_INDEX + 1) / (TOTAL_MONTHS - QI_START_INDEX) : 0;

      var admissions = Math.round(dept.admissions * season * (1 + 0.03 * progress) * (1 + noise(0.06)));
      var discharges = Math.round(admissions * (0.97 + rand() * 0.05));
      var occupancy = clamp(dept.occupancy * season * (1 + noise(0.035)), 45, 99);
      var avgPatients = (dept.beds * occupancy) / 100;
      var patientDays = Math.round(avgPatients * 30);

      var requiredDay = Math.round((avgPatients / dept.ratio) * 30);
      var requiredNight = Math.round((avgPatients / (dept.ratio * 1.2)) * 30);
      var fillBase = 0.965 - (season - 1) * 0.55;
      var fillDay = clamp(fillBase + noise(0.025), 0.84, 1.02);
      var fillNight = clamp(fillBase - 0.025 + noise(0.03), 0.8, 1.0);
      var scheduledDay = Math.round(requiredDay * fillDay);
      var scheduledNight = Math.round(requiredNight * fillNight);

      var mortality = Math.max(0, Math.round(discharges * (dept.mortality / 100) * (1 + noise(0.25))));
      var transfer = Math.round(discharges * (0.07 + noise(0.015)));
      var rehab = Math.round(discharges * (dept.los > 3 ? 0.13 : 0.05) * (1 + noise(0.15)));
      var ama = Math.round(discharges * (0.015 + rand() * 0.01));
      var home = Math.max(0, discharges - mortality - transfer - rehab - ama);

      var readmitRate = dept.readmit * (1 - 0.12 * progress) * (1 + noise(0.08));
      var readmissions = Math.round(discharges * (readmitRate / 100));

      var staffingStress = 1 + Math.max(0, 0.95 - fillDay) * 3;
      var fallsRate = dept.falls * staffingStress * (1 - 0.32 * qiEffect) * (1 + noise(0.18));
      var hapiRate = dept.hapi * staffingStress * (1 - 0.18 * qiEffect) * (1 + noise(0.2));
      var medErrRate = dept.medErr * staffingStress * (1 + noise(0.15));

      var hygiene = clamp(86 + 7.5 * qiEffect + 1.5 * progress + noise(1.6), 80, 99.2);

      return {
        month: m.key,
        label: m.label,
        admissions: admissions,
        discharges: discharges,
        occupancy: occupancy,
        avgPatients: avgPatients,
        patientDays: patientDays,
        losDays: Math.round(dept.los * (1 + noise(0.08)) * discharges * 10) / 10,
        staffing: {
          day: { required: requiredDay, scheduled: scheduledDay },
          night: { required: requiredNight, scheduled: scheduledNight }
        },
        outcomes: { home: home, rehab: rehab, transfer: transfer, ama: ama, deceased: mortality },
        readmissions: readmissions,
        satisfaction: clamp(84 - (season - 1) * 40 + (fillDay - 0.93) * 60 + 3 * progress + noise(2), 70, 96),
        falls: Math.max(0, Math.round((fallsRate * patientDays) / 1000)),
        hapi: Math.max(0, Math.round((hapiRate * patientDays) / 1000)),
        clabsi: rand() < dept.clabsi * (dept.id === "icu" ? 0.35 : 0.12) ? 1 : 0,
        centralLineDays: Math.round(patientDays * (dept.id === "icu" ? 0.6 : 0.2)),
        medErrors: Math.max(0, Math.round((medErrRate * patientDays) / 1000)),
        hygiene: hygiene
      };
    });
  });

  window.HOSPITAL_DATA = {
    isSynthetic: true,
    hospitalName: "Synthetic General Hospital",
    departments: DEPARTMENTS.map(function (d) { return { id: d.id, name: d.name, beds: d.beds }; }),
    months: months,
    records: records,
    targets: { occupancy: 85, falls: 3.0, hapi: 1.0, clabsi: 0.8, medErrors: 2.5, hygiene: 95, fillRate: 95 }
  };
})();
